                        dir = dir.Unit
                        local rel = F.flat(pos) - F.flat(d.From)
                        local along = rel:Dot(dir)
                        local side = (rel - dir * along).Magnitude
                        if along >= -4 and along <= (tonumber(d.Length) or 30) + 4 and side <= (tonumber(d.Width) or 6) / 2 + 4 then hit = true end
                    end
                elseif d.Shape == "Cone" and typeof(d.At) == "Vector3" and typeof(d.Dir) == "Vector3" then
                    local rel = F.flat(pos) - F.flat(d.At)
                    local dir = F.flat(d.Dir)
                    if rel.Magnitude <= (tonumber(d.Range) or 20) + 4 then
                        if rel.Magnitude < 4 or dir.Magnitude == 0 then hit = true
                        elseif math.deg(math.acos(math.clamp(rel.Unit:Dot(dir.Unit), -1, 1))) <= (tonumber(d.Angle) or 45) / 2 + 12 then hit = true end
                    end
                end
            end
        end
        F.DANGER = keep
        return hit
    end
    function F.safeSpot(center)
        local r = hrp()
        local best, bd
        for _, rad in ipairs({ 16, 22, 30, 40 }) do
            for i = 0, 11 do
                local a = i / 12 * math.pi * 2
                local p = center + Vector3.new(math.cos(a) * rad, 3, math.sin(a) * rad)
                if not F.inDanger(p) then
                    local d = r and (p - r.Position).Magnitude or 0
                    if not bd or d < bd then best, bd = p, d end
                end
            end
            if best then return best end
        end
        return center + Vector3.new(45, 3, 0)
    end
    function F.threat(range)
        if not on("fm_fight") then return false end
        local r = hrp()
        local f = Workspace:FindFirstChild("Monsters")
        if not (r and f) then return false end
        for _, c in ipairs(f:GetChildren()) do
            if c:IsA("Model") and c:GetAttribute("DeadAt") == nil and c:GetAttribute("State") ~= "Dead" and c:GetAttribute("State") ~= "Underground" and c:GetAttribute("State") ~= "Sinking" and c:GetAttribute("Hidden") ~= true and F.wants(c) then
                if (c:GetPivot().Position - r.Position).Magnitude <= (range or 35) then return true end
            end
        end
        return false
    end
    function F.fightStep()
        local list = F.monsters(true)
        if #list == 0 then
            F.fighting = false
            if F.hold then local g = F.holdGround; F.hold = nil; if g then F.tp(g + Vector3.new(0, 3, 0)) end end
            return false
        end
        local t = list[1]
        F.fighting = true
        S.task = L["Fighting "] .. tostring(t.m:GetAttribute("Monster") or t.m.Name)
        local r = hrp()
        if not r then return true end
        local tool = F.chopTool()
        F.equip(tool)
        local p = t.m:GetPivot().Position
        F.holdGround = p
        F.holdAt = os.clock()
        local atk = p + Vector3.new(0, F.HOVER, 0)
        if on("cb_dodge") and F.inDanger(atk) then
            local s = F.safeSpot(p)
            F.hold = CFrame.lookAt(s, Vector3.new(p.X, s.Y, p.Z))
            S.task = L["Dodging "] .. tostring(t.m:GetAttribute("Monster") or t.m.Name)
            S.dodges = (S.dodges or 0) + 1
            task.wait(0.12)
            F.holdAt = os.clock()
            return true
        end
        F.hold = CFrame.lookAt(atk, p)
        if F.dynamiteReady() then F.throwDynamite(p) end
        local gun, gc = F.gun()
        if gun and F.shoot(gun, gc, F.monAim(t.m)) then
            F.hitAt[t.m] = os.clock()
            task.wait(1 / math.max(tonumber(gc.Rate) or 4, 1) + 0.02)
            F.holdAt = os.clock()
            return true
        end
        F.asSide = -(F.asSide or 1)
        F.CR.Swing:FireServer(F.asSide)
        F.hitAt[t.m] = os.clock()
        task.wait(math.max(F.interval(tool) * 1.1, 0.12))
        F.holdAt = os.clock()
        return true
    end
    function F.brain()
        while RUNNING do
            local ok, err = pcall(function()
                if not F.ready() then S.task = L["Loading"]; task.wait(1); return end
                local h = hum()
                if not h or h.Health <= 0 then task.wait(0.5); return end
                if not on("fm_on") then if not on("cb_hunt") then S.task = L["Idle"] end; F.lastFell = os.clock(); task.wait(0.3); return end
                F.lastFell = F.lastFell or os.clock()
                if os.clock() - F.lastFell > 60 then
                    F.lastFell = os.clock()
                    F.bad, F.badCount = {}, {}
                    F.deposit()
                    F.equip(F.chopTool())
                    say(L["Got unstuck"])
                end
                if os.clock() - (F.badReset or 0) > 60 then F.badReset = os.clock(); F.bad = {}; F.badCount = {} end
                if on("fm_fight") and F.fightStep() then return end
                if F.cashOut() then task.wait(1); return end
                F.gems()
                local m = F.pickTree()
                if not m then
                    F.deposit()
                    S.task = L["No trees left in open areas"]
                    task.wait(1)
                    return
                end
                if F.handsFull() then S.task = L["Selling"]; F.deposit(); return end
                S.task = L["Chopping "] .. tostring(m:GetAttribute("TreeType") or m.Name)
                local b = F.trunk(m)
                local pos = b and b.Position
                local mut = m:GetAttribute("Mutation")
                F.chopping = true
                local felled = F.chopTree(m)
                F.chopping = false
                if felled then
                    F.lastFell = os.clock()
                    S.felled = S.felled + 1
                    if mut and on("fm_rare") then S.rare = (S.rare or 0) + 1; notify(L["Rare tree felled: "] .. tostring(mut) .. " " .. tostring(m:GetAttribute("TreeType") or m.Name)) end
                    S.task = L["Collecting logs"]
                    do
                        local tw = os.clock()
                        while os.clock() - tw < 1.4 and #F.logsNear(pos, 30) == 0 do task.wait(0.08) end
                        task.wait(0.2)
                    end
                    do
                        local n = #F.logsNear(pos, 30)
                        if n > 0 then F.logsPerTree = (F.logsPerTree or 6.5) * 0.8 + n * 0.2 end
                    end
                    local full = F.collect(pos)
                    if full then F.deposit(); F.collect(pos) end
                    if os.clock() - (F.shopAt or 0) > 3 then
                        F.shopAt = os.clock()
                        local did = false
                        if on("by_tools") then did = F.toolStep() end
                        if not did and on("by_up") then F.upgradeStep(true) end
                        if not did then pcall(CL.step) end
                    end
                    if on("fm_sweep") and os.clock() - (F.sweepAt or 0) > 8 then
                        F.sweepAt = os.clock()
                        if #F.logsNear(nil) > 0 then
                            S.task = L["Picking up loose logs"]
                            if F.collect(nil) then F.deposit(); F.collect(nil) end
                        end
                    end
                end
            end)
            if not ok then F.lastErr = err; task.wait(0.5) end
            task.wait()
        end
    end
    F.UP_W = {
        AxeSharp = 1, AxeSpeed = 1.05, GearBackpack = 0.55, HandsGrasp = 1,
        DynamiteCooldown = 1.5, DynamiteRadius = 1.4,
    }
    function F.upCatalog()
        local labels, map, defaults = {}, {}, {}
        for _, sec in ipairs((F.CFG.Upgrades and F.CFG.Upgrades.Sections) or {}) do
            for _, it in ipairs(sec.Items or {}) do
                local label = tostring(sec.DisplayName or sec.Id) .. " " .. tostring(it.Name or it.Id)
                if map[label] then label = label .. " (" .. it.Id .. ")" end
                labels[#labels + 1] = label
                map[label] = it.Id
                if F.UP_W[it.Id] then defaults[#defaults + 1] = label end
            end
        end
        F.upLabelToId = map
        return labels, defaults
    end
    function F.selected(it)
        local pick = Opt and Opt.up_pick and Opt.up_pick.Value
        if type(pick) ~= "table" then return F.UP_W[it.Id] ~= nil end
        for label, v in pairs(pick) do if v and F.upLabelToId and F.upLabelToId[label] == it.Id then return true end end
        return false
    end
    function F.avgHP()
        if F.hpAt and os.clock() - F.hpAt < 10 then return F.hpCache end
        local unlocked = Workspace:GetAttribute("AreasUnlocked") or 1
        local cur, nxt = { 0, 0 }, { 0, 0 }
        local trees = Workspace:FindFirstChild("Map") and Workspace.Map:FindFirstChild("Trees")
        for _, m in ipairs(trees and trees:GetChildren() or {}) do
            if not m:GetAttribute("Felled") then
                local ai = m:GetAttribute("AreaIndex") or 1
                local hp = tonumber(m:GetAttribute("MaxHP")) or tonumber(m:GetAttribute("HP"))
                if hp and hp > 0 then
                    if ai <= unlocked and cur[2] < 150 then cur[1] = cur[1] + hp; cur[2] = cur[2] + 1
                    elseif ai == unlocked + 1 and nxt[2] < 150 then nxt[1] = nxt[1] + hp; nxt[2] = nxt[2] + 1 end
                end
            end
        end
        local left = tonumber(Workspace:GetAttribute("AreaLeft")) or 100
        local wNext = nxt[2] > 0 and math.clamp(1 - left / 60, 0, 0.8) or 0
        local hc = cur[2] > 0 and cur[1] / cur[2] or 6
        local hn = nxt[2] > 0 and nxt[1] / nxt[2] or hc
        F.hpCache = { cur = hc, nxt = hn, w = wNext }
        F.hpAt = os.clock()
        return F.hpCache
    end
    function F.estTime(bump)
        local function lv(id) return (tonumber(attr("Up_" .. id, 0)) or 0) + ((bump == id) and 1 or 0) end
        local tool = F.chopTool()
        local axe = tool == "Axe"
        local dmg = F.toolDmg(tool) * (1 + 0.125 * ((axe and bump == "AxeSharp") and 1 or 0))
        local gap = F.interval(tool) * (0.938083151964686 ^ ((axe and bump == "AxeSpeed") and 1 or 0)) * 1.1 + 0.06
        local grab = ({ 1, 2, 3, 5 })[math.min(lv("HandsGrasp"), 3) + 1]
        local carry = ({ 5, 15, 30, 80, 155 })[math.min(lv("GearBackpack"), 4) + 1]
        local logs = F.logsPerTree or 6.5
        local hpc = F.avgHP()
        local function per(hp)
            local hits = math.max(1, math.ceil(hp / dmg - 1e-6))
            return 2.0 + hits * gap + math.ceil(logs / grab) * 0.32 + (logs / carry) * 1.15
        end
        return per(hpc.cur) * (1 - hpc.w) + per(hpc.nxt) * hpc.w
    end
    F.SMART = { AxeSharp = true, AxeSpeed = true, HandsGrasp = true, GearBackpack = true, HandsSpeed = true }
    F.FLAT = { GearChipper = 0.0005, DynamiteCooldown = 0.02, DynamiteRadius = 0.015 }
    function F.scoreFor(it, price)
        if not (price and F.selected(it)) then return nil end
        if val("up_order", "Smart") == "Cheapest First" then return price end
        local gain
        if F.SMART[it.Id] then
            local t0 = F.estTime(nil)
            gain = (t0 - F.estTime(it.Id)) / t0
        else
            gain = F.FLAT[it.Id]
            if gain == nil then gain = 0.002 end
            if it.Id:find("^Dynamite") and not on("fm_dyn") then gain = 0.002 end
        end
        if gain <= 1e-4 then return nil end
        return price / gain
    end
    function F.reserve()
        if not on("by_tools") then return 0 end
        for _, name in ipairs(F.TOOL_ORDER) do
            if not attr("Owns" .. name) then
                local t = F.CFG.Tools and F.CFG.Tools[name]
                return type(t) == "table" and tonumber(t.Price) or 0, name
            end
        end
        return 0
    end
    function F.plan()
        local money = cash()
        local res, rname = F.reserve()
        local best, bs, bprice
        for _, sec in ipairs((F.CFG.Upgrades and F.CFG.Upgrades.Sections) or {}) do
            if (not sec.Requires) or attr("Owns" .. tostring(sec.Requires)) == true then
                for _, it in ipairs(sec.Items or {}) do
                    local lvl = tonumber(attr("Up_" .. it.Id, 0)) or 0
                    local price = it.Prices and it.Prices[lvl + 1]
                    local sc = F.scoreFor(it, price)
                    if sc then
                        local s = sc
                        if not bs or s < bs then best, bs, bprice = it, s, price end
                    end
                end
            end
        end
        return best, bprice, res, rname, money
    end
    function F.upgradeStep(allowTP)
        local money = cash()
        local res = F.reserve()
        local best, bs
        for _, sec in ipairs((F.CFG.Upgrades and F.CFG.Upgrades.Sections) or {}) do
            local okTool = (not sec.Requires) or attr("Owns" .. tostring(sec.Requires)) == true
            if okTool then
                for _, it in ipairs(sec.Items or {}) do
                    if (allowTP or not it.Station) and not (F.upFail[it.Id] and F.upFail[it.Id] > os.clock()) then
                        local lvl = tonumber(attr("Up_" .. it.Id, 0)) or 0
                        local price = it.Prices and it.Prices[lvl + 1]
                        local sc = F.scoreFor(it, price)
                        if sc and price <= money and (res == 0 or money - price >= res or price <= res * 0.06) then
                            local s = sc
                            if not bs or s < bs then best, bs = it, s end
                        end
                    end
                end
            end
        end
        if not best then return false end
        local lvl0 = tonumber(attr("Up_" .. best.Id, 0)) or 0
        local back
        if best.Station then
            local st = Workspace.Map:FindFirstChild("LogCabin") and Workspace.Map.LogCabin:FindFirstChild("Shop") and Workspace.Map.LogCabin.Shop.Stations:FindFirstChild("Station_" .. best.Station)
            if not st then F.upFail[best.Id] = os.clock() + 60; return false end
            local r = hrp(); back = r and r.CFrame
            F.tp(st:GetPivot().Position + Vector3.new(0, 3, 4))
            task.wait(0.5)
        end
        F.CR.BuyUpgrade:FireServer(best.Id)
        task.wait(0.6)
        if back then local r = hrp(); if r then r.CFrame = back end end
        if (tonumber(attr("Up_" .. best.Id, 0)) or 0) > lvl0 then S.buys = S.buys + 1; say(L["Upgraded "] .. tostring(best.Name or best.Id)); return true end
        F.upFail[best.Id] = os.clock() + 20
        return false
    end
    F.TOOL_ORDER = { "Axe", "Dynamite" }
    function F.toolStep()
        for _, name in ipairs(F.TOOL_ORDER) do
            if not attr("Owns" .. name) and not (F.toolFail[name] and F.toolFail[name] > os.clock()) then
                local t = F.CFG.Tools and F.CFG.Tools[name]
                local price = type(t) == "table" and tonumber(t.Price) or (name == "Axe" and 150 or 2500)
                if cash() < price then return false end
                local st = Workspace.Map:FindFirstChild("LogCabin") and Workspace.Map.LogCabin:FindFirstChild("Shop")
                st = st and st.Stations
                local station
                if st then for _, s in ipairs(st:GetChildren()) do if s:GetAttribute("ShopItem") == name then station = s end end end
                if not station then F.toolFail[name] = os.clock() + 60; return false end
                local r = hrp(); local back = r and r.CFrame
                F.tp(station:GetPivot().Position + Vector3.new(0, 3, 4))
                task.wait(0.6)
                local ok, res = pcall(function() return F.CR.BuyTool:InvokeServer(name) end)
                task.wait(0.3)
                if back then r = hrp(); if r then r.CFrame = back end end
                if ok and type(res) == "table" and res.Ok then S.buys = S.buys + 1; say(L["Bought "] .. name); F.equip(F.chopTool()); return true end
                F.toolFail[name] = os.clock() + 30
                return false
            end
        end
        return false
    end
    function F.shopLoop()
        while RUNNING do
            if F.ready() and not F.busyShop then
                F.busyShop = true
                pcall(function()
                    if on("by_up") and not (on("fm_on") and F.chopping) then F.upgradeStep(not on("fm_on")) end
                end)
                F.busyShop = false
            end
            task.wait(1)
        end
    end
    function F.reach(tool)
        local t = F.CFG and F.CFG.Tools and F.CFG.Tools[tool]
        local sr = type(t) == "table" and tonumber(t.ServerReach) or 11
        if sr <= 0 then sr = 11 end
        return math.min(val("as_reach", 12), sr - 0.5)
    end
    function F.pickRange() return val("as_pickr", 11) end
    F.rings = {}
    function F.ring(key, color)
        local a = F.rings[key]
        if a and a.Parent then return a end
        a = Instance.new("CylinderHandleAdornment")
        a.Color3 = color
        a.Transparency = 0.3
        a.Height = 0.12
        a.Adornee = Workspace.Terrain
        local root = (gethui and pcall(gethui) and gethui()) or game:GetService("CoreGui")
        pcall(function() a.Parent = root end)
        if not a.Parent then a.Parent = Workspace.Terrain end
        F.rings[key] = a
        return a
    end
    onClean(function() for _, a in pairs(F.rings) do pcall(function() a:Destroy() end) end end)
    track(RunService.RenderStepped:Connect(function()
        local r, h = hrp(), hum()
        if not (on("as_show") and r and h) then for _, a in pairs(F.rings) do a.Visible = false end return end
        local y = r.Position.Y - h.HipHeight - r.Size.Y / 2 + 0.08
        local function put(key, color, c, rad)
            local a = F.ring(key, color)
            a.Visible = true
            a.Radius = rad
            a.InnerRadius = math.max(rad - 0.3, 0)
