        end
        put("chop", Color3.fromRGB(90, 220, 110), r.Position, F.reach(F.lastTool or attr("Tool") or "Fists"))
        put("pick", Color3.fromRGB(90, 170, 255), r.Position, F.pickRange())
        if on("as_aura") then put("aura", Color3.fromRGB(255, 160, 60), F.auraAnchor or r.Position, val("as_range", 40))
        elseif F.rings.aura then F.rings.aura.Visible = false end
    end))
    function F.killStep()
        if not on("as_kill") or F.fightOn() then return false end
        local r = hrp()
        if not r then return false end
        local tool = F.chopTool()
        local gun, gc = F.gun()
        local reach = gun and math.min((tonumber(gc.Range) or 110) - 10, val("cb_gunr", 80)) or (F.reach(tool) + 3)
        local best
        for _, t in ipairs(F.monsters(true)) do if t.d <= reach and (not best or t.d < best.d) then best = t end end
        if not best then return false end
        if os.clock() < (F.killNext or 0) then return true end
        if gun then
            if F.shoot(gun, gc, F.monAim(best.m)) then F.hitAt[best.m] = os.clock() end
            S.task = L["Shooting "] .. tostring(best.m:GetAttribute("DisplayName") or best.m:GetAttribute("Monster") or "monster")
            F.killNext = os.clock() + 1 / math.max(tonumber(gc.Rate) or 4, 1) + 0.02
            return true
        end
        if attr("Tool") ~= tool then F.CR.EquipTool:FireServer(tool) end
        r.CFrame = CFrame.lookAt(r.Position, Vector3.new(best.p.X, r.Position.Y, best.p.Z))
        F.asSide = -(F.asSide or 1)
        F.CR.Swing:FireServer(F.asSide)
        F.hitAt[best.m] = os.clock()
        S.task = L["Hitting "] .. tostring(best.m:GetAttribute("Monster") or best.m.Name)
        F.killNext = os.clock() + math.max(F.interval(tool) * 1.1, 0.15)
        return true
    end
    F.flameTry = setmetatable({}, { __mode = "k" })
    function F.flameOff()
        if F.flaming then F.flaming = false pcall(function() F.CR.Flame:FireServer(false) end) end
    end
    function F.flameStep()
        if not on("as_flame") or attr("OwnsFlamethrower") ~= true or not F.CR.Ignite then F.flameOff() return false end
        local r = hrp()
        if not r then return false end
        local fc = (F.CFG and F.CFG.Flamethrower) or {}
        local range = math.min((tonumber(fc.Range) or 14) + 2, (tonumber(fc.ServerRange) or 18) - 1)
        local unlocked = Workspace:GetAttribute("AreasUnlocked") or 1
        local trees = Workspace:FindFirstChild("Map") and Workspace.Map:FindFirstChild("Trees")
        local list = {}
        for _, m in ipairs(trees and trees:GetChildren() or {}) do
            if m:IsA("Model") and not F.bad[m] and not m:GetAttribute("Felled") and not m:GetAttribute("Doomed") and m:GetAttribute("BurnUntil") == nil and (m:GetAttribute("AreaIndex") or 1) <= unlocked and (tonumber(m:GetAttribute("HP")) or 0) > 0 then
                local b = F.trunk(m)
                if b then
                    local d = Vector3.new(b.Position.X - r.Position.X, 0, b.Position.Z - r.Position.Z).Magnitude
                    if d <= range then list[#list + 1] = { m = m, b = b, d = d } end
                end
            end
        end
        if #list == 0 then F.flameOff() return false end
        if attr("Tool") ~= "Flamethrower" then F.CR.EquipTool:FireServer("Flamethrower") task.wait(0.3) end
        if not F.flaming or attr("Flaming") ~= true then F.flaming = true F.CR.Flame:FireServer(true) task.wait(0.2) end
        table.sort(list, function(a, c) return a.d < c.d end)
        for i = 1, math.min(#list, 6) do
            local t = list[i]
            local rr = hrp()
            if not rr then break end
            rr.CFrame = CFrame.lookAt(rr.Position, Vector3.new(t.b.Position.X, rr.Position.Y, t.b.Position.Z))
            task.wait(0.06)
            F.CR.Ignite:FireServer(t.m)
            F.flameTry[t.m] = (F.flameTry[t.m] or 0) + 1
            if F.flameTry[t.m] > 8 then F.bad[t.m] = true end
        end
        S.task = L["Burning "] .. #list .. L[" tree"] .. (#list == 1 and "" or "s")
        task.wait(0.35)
        return true
    end
    F.asNext = 0
    function F.assistStep()
        if F.killStep() then return end
        if on("fm_on") then return end
        local r = hrp()
        local h = hum()
        if not (r and h and h.Health > 0) then return end
        if on("as_pick") and not F.bagFull() then
            for _, l in ipairs(F.logsNear(r.Position, F.pickRange())) do
                if F.bagFull() then break end
                F.CR.PickUpLog:FireServer(l.m)
                task.wait(0.13)
            end
        end
        if on("as_gem") then
            for _, g in ipairs(CollectionService:GetTagged("GemDrop")) do
                if g:IsA("BasePart") and g.Parent and g:GetAttribute("Owner") == lp.UserId and not g:GetAttribute("CollectedBy") and (g.Position - r.Position).Magnitude < 14 then
                    F.CR.CollectGem:FireServer(g, "Click")
                end
            end
        end
        if F.flameStep() then return end
        if on("as_chop") and not F.handsFull() and os.clock() >= F.asNext then
            local cur = attr("Tool")
            if not F.TOOL_OK[cur] then return end
            local tool = F.chopTool()
            local aura = on("as_aura")
            local reach = F.reach(tool)
            if aura and not F.auraAnchor then F.auraAnchor = r.Position end
            local center = aura and F.auraAnchor or r.Position
            local radius = aura and val("as_range", 40) or reach
            local unlocked = Workspace:GetAttribute("AreasUnlocked") or 1
            local trees = Workspace:FindFirstChild("Map") and Workspace.Map:FindFirstChild("Trees")
            local hits = {}
            for _, m in ipairs(trees and trees:GetChildren() or {}) do
                if m:IsA("Model") and not F.bad[m] and not m:GetAttribute("Felled") and not m:GetAttribute("Doomed") and (m:GetAttribute("AreaIndex") or 1) <= unlocked and (tonumber(m:GetAttribute("HP")) or 0) > 0 then
                    local b = F.trunk(m)
                    if b and Vector3.new(b.Position.X - center.X, 0, b.Position.Z - center.Z).Magnitude <= radius then
                        hits[#hits + 1] = { m = m, b = b, d = Vector3.new(b.Position.X - r.Position.X, 0, b.Position.Z - r.Position.Z).Magnitude }
                    end
                end
            end
            if #hits == 0 then
                if F.revving then F.rev(false) end
                if aura and (r.Position - center).Magnitude > 12 then F.tp(center + Vector3.new(0, 3, 0)) end
                return
            end
            table.sort(hits, function(a, c) return a.d < c.d end)
            if cur ~= tool then F.CR.EquipTool:FireServer(tool) end
            local t = hits[1]
            if aura and t.d > reach - 2 then
                F.tp(t.b.Position + Vector3.new(3.5, 2.5, 0), t.b.Position)
                F.asNext = os.clock() + 0.55
                return
            end
            local flat = Vector3.new(r.Position.X - t.b.Position.X, 0, r.Position.Z - t.b.Position.Z)
            local dir = flat.Magnitude > 0.1 and flat.Unit or Vector3.new(1, 0, 0)
            local hit = Vector3.new(t.b.Position.X, t.b.Position.Y + 1.2, t.b.Position.Z) + dir * 0.7
            F.asSide = -(F.asSide or 1)
            F.cut(tool, t.m, hit, F.asSide)
            F.asNext = os.clock() + F.interval(tool) * 1.1 + 0.06 - (F.isSaw(tool) and 0 or 0.1)
        end
    end
    function F.assistLoop()
        while RUNNING do
            if F.ready() then pcall(F.assistStep) end
            task.wait(0.05)
        end
    end
    function F.huntLoop()
        while RUNNING do
            local busy = false
            if F.ready() and on("cb_hunt") and not on("fm_on") then
                local h = hum()
                if h and h.Health > 0 then
                    local ok, b = pcall(F.fightStep)
                    busy = ok and b
                    if not busy then S.task = L["Hunting · no monsters you picked"] end
                end
            end
            task.wait(busy and 0.03 or 0.5)
        end
    end
    function F.birdLoop()
        while RUNNING do
            if F.ready() and on("fm_birds") then
                local r = hrp()
                if r then
                    local c0 = cash()
                    pcall(function() F.CR.PopBird:FireServer(r.Position + Vector3.new(math.random(-3, 3), 4, math.random(-3, 3))) end)
                    S.birds = S.birds + 1
                end
            end
            task.wait(0.85)
        end
    end
end
