function CL.csv(s) local t = {} for p in tostring(s or ""):gmatch("[^,]+") do t[p] = true end return t end
function CL.list() return (CL.CFG and CL.CFG.Classes and CL.CFG.Classes.List) or {} end
function CL.info(id) for _, c in ipairs(CL.list()) do if c.Id == id then return c end end end
function CL.score(id)
    local c = CL.info(id)
    local p = (c and c.Perks) or {}
    return (p.Power or 0) + (p.Sell or 0) + (p.Carry or 0) * 0.04 + (p.Speed or 0) * 0.6 + (p.Luck or 0) * 0.3
end
function CL.price(id) local st = CL.CFG and CL.CFG.Classes and CL.CFG.Classes.Stock return st and st.Prices and st.Prices[id] end
function CL.ids() local t = {} for _, c in ipairs(CL.list()) do if (CL.price(c.Id) or 0) > 0 then t[#t + 1] = c.Id end end return t end
function CL.allowed(id)
    local pick = Opt and Opt.cl_pick and Opt.cl_pick.Value
    if type(pick) ~= "table" then return true end
    return pick[id] == true
end
function CL.stand()
    local m = Workspace:FindFirstChild("Map") and Workspace.Map:FindFirstChild("ClassStand")
    if m then return m end
    local lb = Workspace:FindFirstChild("Lobby")
    if lb then for _, d in ipairs(lb:GetDescendants()) do if d:GetAttribute("LobbyCopyOf") == "ClassStand" then return d end end end
end
function CL.tp(pos)
    local r = hrp()
    if not r then return end
    local h = hum()
    if h and h.Sit then h.Sit = false end
    r.CFrame = CFrame.new(pos)
    r.AssemblyLinearVelocity = Vector3.zero
end
function CL.bestOwned()
    local best, bs
    for id in pairs(CL.csv(attr("ClassesOwned", ""))) do local sc = CL.score(id) if not bs or sc > bs then best, bs = id, sc end end
    return best, bs or 0
end
function CL.target()
    local _, base = CL.bestOwned()
    local owned = CL.csv(attr("ClassesOwned", ""))
    local best, bs
    for id in pairs(CL.csv(Workspace:GetAttribute("ClassStock"))) do
        if not owned[id] and CL.allowed(id) and CL.price(id) and CL.score(id) > base and (not bs or CL.score(id) > bs) then best, bs = id, CL.score(id) end
    end
    return best
end
function CL.step()
    if not CL.CR then return false end
    if on("cl_equip") then
        local b = CL.bestOwned()
        if b and b ~= attr("Class") and os.clock() > (CL.eqAt or 0) then CL.eqAt = os.clock() + 5; CL.CR.EquipClass:FireServer(b); return false end
    end
    if not on("cl_auto") or os.clock() < (CL.failUntil or 0) then return false end
    local id = CL.target()
    if not id or (tonumber(attr("Gems", 0)) or 0) < (CL.price(id) or math.huge) then return false end
    local st = CL.stand()
    if not st then return false end
    local r = hrp()
    local back = r and r.CFrame
    CL.tp(st:GetPivot().Position + Vector3.new(0, 3, 5))
    task.wait(0.6)
    local ok, res = pcall(function() return CL.CR.BuyClass:InvokeServer(id) end)
    task.wait(0.3)
    if back then local r2 = hrp(); if r2 then r2.CFrame = back end end
    if ok and type(res) == "table" and res.Ok then
        S.buys = S.buys + 1
        notify(L["Got class "] .. id)
        CL.CR.EquipClass:FireServer(id)
        return true
    end
    CL.failUntil = os.clock() + 30
    return false
end
CL.RANK = { Common = 1, Uncommon = 2, Rare = 3, Epic = 4, Legendary = 5, Mythic = 6, Secret = 7 }
function CL.alertLoop()
    local last
    while RUNNING do
        local st = Workspace:GetAttribute("ClassStock")
        if st ~= last then
            last = st
