    end
end
function GP.perks() return (CL.CFG and CL.CFG.Shop and CL.CFG.Shop.Perks) or {} end
GP.W = { Sell = 1, Luck = 0.3, Carry = 0.04, Gems = 0.5, Power = 1, Speed = 0.6 }
function GP.options()
    local list = {}
    local pick = Opt and Opt.gp_pick and Opt.gp_pick.Value
    if on("gp_auto") then
        for _, p in ipairs(GP.perks()) do
            if type(pick) ~= "table" or pick[p.Id] then
                local lvl = tonumber(attr("GemPerk_" .. p.Id, 0)) or 0
                local price = p.Prices and p.Prices[lvl + 1]
                if price then list[#list + 1] = { kind = "perk", id = p.Id, price = price, value = (p.PerLevel or 0) * (GP.W[p.Perk] or 0.1) } end
            end
        end
    end
    if on("cl_auto") then
        local _, base = CL.bestOwned()
        local owned = CL.csv(attr("ClassesOwned", ""))
        for id in pairs(CL.csv(Workspace:GetAttribute("ClassStock"))) do
            local price = CL.price(id)
            if price and not owned[id] and CL.allowed(id) and CL.score(id) > base then list[#list + 1] = { kind = "class", id = id, price = price, value = CL.score(id) - base } end
        end
    end
    table.sort(list, function(x, y) return x.value / x.price > y.value / y.price end)
    return list
end
function GP.step()
    if not CL.CR or os.clock() < (GP.failUntil or 0) then return false end
    local gems = tonumber(attr("Gems", 0)) or 0
    local list = GP.options()
    local pickIt
    for _, o in ipairs(list) do
        if o.price <= gems then pickIt = o break end
        if on("gp_save") then GP.saving = o break end
    end
    if pickIt then GP.saving = nil end
    if not pickIt then return false end
    if pickIt.kind == "class" then
        local st = CL.stand()
        if not st then GP.failUntil = os.clock() + 30; return false end
        CL.tp(st:GetPivot().Position + Vector3.new(0, 3, 5))
        task.wait(0.6)
        local ok, res = pcall(function() return CL.CR.BuyClass:InvokeServer(pickIt.id) end)
        if ok and type(res) == "table" and res.Ok then S.buys = S.buys + 1; notify(L["Got class "] .. pickIt.id); CL.CR.EquipClass:FireServer(pickIt.id); return true end
        GP.failUntil = os.clock() + 30
        GP.lastWhy = ok and type(res) == "table" and tostring(res.Why) or tostring(res)
        return false
    end
    local ok, res = pcall(function() return CL.CR.BuyGemPerk:InvokeServer(pickIt.id) end)
    if ok and type(res) == "table" and res.Ok then S.buys = S.buys + 1; say(L["Perk "] .. pickIt.id .. L[" level "] .. tostring(res.Level)); return true end
    GP.failUntil = os.clock() + 20
    GP.lastWhy = ok and type(res) == "table" and tostring(res.Why) or tostring(res)
    return false
end
function GP.eventKey()
    local ok, C = pcall(require, SHARED:FindFirstChild("Configs") and SHARED.Configs:FindFirstChild("Chapters"))
    if ok and type(C) == "table" then
        if type(C.Graveyard) == "table" then return "Graveyard" end
        for k, v in pairs(C) do if type(v) == "table" and type(v.Lobby) == "table" and v.Lobby.Chip == "EVENT" and not tostring(k):find("Test") then return k end end
    end
    return "Graveyard"
end
function GP.joinEvent()
    if not on("lb_event") or os.clock() < (GP.evNext or 0) then return end
    GP.evNext = os.clock() + 12
    local LR = ReplicatedStorage:FindFirstChild("Lobby")
    local R = LR and LR:FindFirstChild("Remotes")
    local pads = Workspace:FindFirstChild("Lobby") and Workspace.Lobby:FindFirstChild("LobbyPads")
    local r = hrp()
    if not (R and R:FindFirstChild("CreateParty") and pads and r) then return end
    local got
    local con = R.OpenCreate.OnClientEvent:Connect(function(p) if type(p) == "string" then got = p end end)
    for _, pad in ipairs(pads:GetChildren()) do
        if got or not on("lb_event") then break end
        r = hrp()
        if r then r.CFrame = CFrame.new(pad:GetPivot().Position + Vector3.new(0, 3.5, 0)) end
        local t0 = os.clock()
        while not got and os.clock() - t0 < 2.5 do task.wait(0.1) end
    end
    con:Disconnect()
    if not got then say(L["Event: no free pad, retrying"]) return end
    task.wait(0.4)
    local ok, res = pcall(function() return R.CreateParty:InvokeServer(got, val("lb_diff", "NORMAL"), 1, GP.eventKey(), on("lb_peace") == true) end)
    if ok and type(res) == "table" and res.Ok then
        say(L["Event run starting"])
        GP.evNext = os.clock() + 45
    else
        say(L["Event join failed: "] .. tostring(type(res) == "table" and (res.Why or res.Error or res.Message) or res))
    end
end
function GP.lobbyLoop()
    while RUNNING do
        pcall(GP.joinEvent)
        pcall(function()
            if on("cl_equip") then
                local bo = CL.bestOwned()
                if bo and bo ~= attr("Class") and os.clock() > (CL.eqAt or 0) then CL.eqAt = os.clock() + 5; CL.CR.EquipClass:FireServer(bo) end
            end
            GP.step()
        end)
        task.wait(1.5)
    end
end
