local PT = { last = "" }
function PT.remote()
    local pe = ReplicatedStorage:FindFirstChild("PetEggs")
    return pe and pe:FindFirstChild("PetInventory")
end
function PT.cfg()
    if PT.EC == nil then
        local pe = ReplicatedStorage:FindFirstChild("PetEggs")
        local ok, m = pcall(function() return require(pe.EggConfig) end)
        PT.EC = ok and m or false
    end
    return PT.EC or nil
end
function PT.inv()
    local ok, t = pcall(function() return HttpService:JSONDecode(lp:GetAttribute("PetInventory") or "{}") end)
    return ok and type(t) == "table" and t or {}
end
function PT.eggs()
    local e, out = PT.inv().Eggs, {}
    if type(e) ~= "table" then return out end
    for k, v in pairs(e) do
        if type(k) == "number" then
            local n = type(v) == "table" and (v.Key or v.Egg or v.Name) or v
            if n then out[tostring(n)] = (out[tostring(n)] or 0) + 1 end
        elseif tonumber(v) then out[k] = tonumber(v) end
    end
    return out
end
function PT.price(egg)
    local ec = PT.cfg()
    local ok, p = pcall(function() return ec.OpenPrice(egg) end)
    return ok and tonumber(p) or math.huge
end
function PT.step()
    local r = PT.remote()
    if not r then return end
    if on("pt_open") then
        for egg, n in pairs(PT.eggs()) do
            if n > 0 then
                local price = PT.price(egg)
                local gems = tonumber(attr("Gems", 0)) or 0
                if price == 0 or (on("pt_paid") and price <= gems) then
                    local ok, okv = pcall(r.InvokeServer, r, "OpenEgg", egg)
                    if ok and okv then S.hatched = (S.hatched or 0) + 1; say(L["Hatched "] .. egg) end
                    task.wait(2.5)
                    return
                end
            end
        end
    end
    if on("pt_best") then
        local t = PT.inv()
        local key = #(t.Pets or {}) .. "|" .. HttpService:JSONEncode(t.Equipped or {})
        if key ~= PT.last and #(t.Pets or {}) > 0 then
            PT.last = key
            pcall(r.InvokeServer, r, "EquipBest")
            task.wait(1)
            local t2 = PT.inv()
            PT.last = #(t2.Pets or {}) .. "|" .. HttpService:JSONEncode(t2.Equipped or {})
        end
    end
end
task.spawn(function()
    while RUNNING do
        pcall(PT.step)
        if UI.pets then
            local t = PT.inv()
            local ne = 0 for _, n in pairs(PT.eggs()) do ne += n end
            setText(UI.pets, string.format(L["Pets %d · Equipped %d/%d · Eggs %d"], #(t.Pets or {}), #(t.Equipped or {}), tonumber(t.Max) or 3, ne))
        end
        task.wait(2)
    end
end)
