            setText(UI.stats3, string.format(L["Area %s · %s trees left · Bag %s"], tostring(Workspace:GetAttribute("AreaCurrent") or "-"), tostring(Workspace:GetAttribute("AreaLeft") or "-"), tostring(attr("CarriedLogs", 0))))
            if UI.mon1 then
                local mins, boss, near = 0, nil, nil
                for _, t in ipairs(F.monsters()) do
                    if t.boss then boss = boss or t else mins = mins + 1 end
                    if not near or t.d < near then near = t.d end
                end
                setText(UI.mon1, string.format(L["Monsters %d · nearest %s"], mins, near and (math.floor(near) .. L[" studs"]) or "-"))
                if boss then
                    setText(UI.mon2, string.format(L["Boss: %s %s/%s HP"], tostring(boss.m:GetAttribute("DisplayName") or boss.m.Name), short(tonumber(boss.m:GetAttribute("HP")) or 0), short(tonumber(boss.m:GetAttribute("MaxHP")) or 0)))
                else setText(UI.mon2, L["Boss: not awake · clear the area"]) end
                setText(UI.mon3, L["Kills "] .. tostring(S.kills or 0))
